#!/usr/bin/env python3
"""Generate C2_REPORT.md from c2_controls_results.json (RULES rule 6: no hand-transcribed
numbers). Run from this directory after `cd R1 && python3 c2_controls.py`."""
import json
import os

here = os.path.dirname(os.path.abspath(__file__))
d = json.load(open(os.path.join(here, "c2_controls_results.json")))
g, ng, f = d["C2_G_ou_gaussian"], d["C2_NG_affine_exact_control"], d["C2_F_filtered"]
bri1 = d["scale_reference"]["BRI1_witness_abs_gamma1_NB4_tstar0.5"]

lines = [
    "# WO-001 C2 — exogenous controls: REPORT (numbers only)",
    "",
    "Generated by `make_c2_report.py` from `c2_controls_results.json`, which is produced "
    "by `R1/c2_controls.py`. Do not edit by hand.",
    "",
    "| Control | Quantity | Value | Pass condition | Pass |",
    "|---|---|---|---|---|",
    f"| C2-G (Gaussian, colored) | E₂± skewness witness | {g['witness']:.1e} | = 0 exactly | {g['witness'] == 0} |",
    f"| C2-NG (affine entry; exact control) | E₂± skewness witness | {ng['witness_abs']:.3e} | = 0 | {ng['witness_abs'] == 0} |",
    f"| C2-NG | recovered-driver max deviation | {ng['recovered_xi_max_dev']:.2e} | ≤ 1e-12 | {ng['recovered_xi_max_dev'] <= 1e-12} |",
    f"| C2-F (calibrated filters, τ = {tuple(f['taus'])}) | E₂± skewness witness (max over times, at k* = {f['k_max']}) | {f['witness_abs_max']:.6f} | > 0 (correct value under E₂±) | {f['witness_abs_max'] > 0} |",
    f"| C2-F | γ₁ P1(k*), P2(k*) | {f['gamma1_P1_at_kmax']:+.6f}, {f['gamma1_P2_at_kmax']:+.6f} | — | — |",
    f"| C2-F | ε_R with filters in T (T_lin/T_caus on the complete grid): deconvolution max / relative deviation | {f['enlarged_T']['recovered_xi_max_dev']:.2e} / {f['enlarged_T']['recovered_xi_rel_dev']:.2e} | ≤ 1e-12 | {f['enlarged_T']['recovered_xi_max_dev'] <= 1e-12} |",
    "",
    "**Scale reference.**",
    f"- BRI1 witness |γ₁| at t* = 0.5 and N_B = 4 (from C1): {bri1:.6e}.",
    f"- C2-F witness / BRI1 witness = {f['witness_abs_max'] / bri1:.3e}.",
    "",
    "**Sampled noise floor.**",
    f"- Max over the 64 grid times of |γ̂_A − γ̂_B|, from 2 independent batches of "
    f"{f['sampled_noise_floor_paths_per_batch']} path samples each: "
    f"{f['sampled_noise_floor_max_over_times']:.3e}.",
    "",
    "**Reading.**",
    "- All exact controls pass.",
    "- C2-F is nonzero under E₂± and zero under linear interfaces on the complete grid. "
    "That is the correct value for each class, not a false positive "
    "(`PROGRAM/RESULTS/R1/R1_T_LADDER.md`; owner ruling G2-01 item 5).",
]
open(os.path.join(here, "C2_REPORT.md"), "w").write("\n".join(lines) + "\n")
print("\n".join(lines))
